[CmdletBinding()]
param([string]$CatalogPath='ES/Output/ResourceReader/resource-reference-catalog.json',[string]$Guid,[string]$SourceId='', [int]$MaxResults=256)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($Guid)-or $Guid -notmatch '^[0-9a-fA-F]{32}$'){throw 'Guid must be a 32-character hexadecimal value'};$catalog=Get-Content -LiteralPath (Resolve-Path -LiteralPath $CatalogPath) -Raw -Encoding UTF8|ConvertFrom-Json;if($catalog.catalogId -ne 'es-resource-reader.reference-catalog.v1'){throw 'invalid reference catalog'};$key=$Guid.ToLowerInvariant();$hits=@($catalog.references|Where-Object {$_.guid -eq $key}|ForEach-Object {$_.references}|Where-Object {[string]::IsNullOrWhiteSpace($SourceId)-or $_.sourceId -eq $SourceId}|Sort-Object sourceId,sourcePath,objectStableId|Select-Object -First ([Math]::Max(1,$MaxResults)));[ordered]@{queryId='es-resource-reader.reference-catalog-query.v1';guid=$key;sourceId=$SourceId;matchedCount=$hits.Count;references=$hits;nonClaims=@('semantic completeness','Unity import','runtime behavior')}|ConvertTo-Json -Depth 10
